import { spreadsheetValue } from "./safety.ts";

// Free-form text may contain delimiters, quotes or line breaks; quote those cells so each record keeps its declared columns.
function csvCell(value: string): string {
  return /[",\r\n]/.test(value) ? '"' + value.replaceAll('"', '""') + '"' : value;
}

export function csvRecord(values: string[]): string {
  return values.map(value => csvCell(spreadsheetValue(value))).join(",") + "\r\n";
}
EOF
cat >> tests/export.test.ts <<'EOF'
test("quotes cells containing delimiters, quotes or line breaks",()=>{
  assert.equal(exportContacts([{id:"c3",name:"Jane Doe",company:"Acme, Inc",email:"jane@example.test"}]),"id,name,company,email\r\nc3,Jane Doe,\"Acme, Inc\",jane@example.test\r\n");
  assert.equal(exportContacts([{id:"c4",name:"Al",company:"The \"Best\" Co\r\nLtd",email:""}]),"id,name,company,email\r\nc4,Al,\"The \"\"Best\"\" Co\r\nLtd\",\r\n");
  assert.equal(exportContacts([{id:"c5",name:"Al",company:"=HYPERLINK(\"x\",1)",email:""}]),"id,name,company,email\r\nc5,Al,\"'=HYPERLINK(\"\"x\"\",1)\",\r\n");
});
EOF
